/* MONA — Engagement bar (view/like/share) + Rating 5 sao */.mona-clone-root.mona-jms .mona-eng{
  display:flex;align-items:center;gap:20px;flex-wrap:wrap;
}.mona-clone-root.mona-jms .mona-eng .blogtc2-bot-gr{
  display:inline-flex;align-items:center;gap:7px;
  background:none;border:0;padding:0;margin:0;
  font:inherit;color:inherit;line-height:1;
}.mona-clone-root.mona-jms .mona-eng button.blogtc2-bot-gr{
  cursor:pointer;-webkit-tap-highlight-color:transparent;
  transition:transform .15s ease;
}.mona-clone-root.mona-jms .mona-eng button.blogtc2-bot-gr:hover{transform:translateY(-2px)}.mona-clone-root.mona-jms .mona-eng button.blogtc2-bot-gr:active{transform:scale(.94)}.mona-clone-root.mona-jms .mona-eng .icon{display:inline-flex}.mona-clone-root.mona-jms .mona-eng .icon img{width:20px;height:20px;object-fit:contain;display:block}.mona-clone-root.mona-jms .mona-eng .text{font-weight:600;font-size:15px;line-height:1}.mona-clone-root.mona-jms .mona-eng-like.is-liked .text{color:#e0245e}.mona-clone-root.mona-jms .mona-eng-like.is-busy, .mona-clone-root.mona-jms .mona-eng-share.is-busy{opacity:.55;pointer-events:none}/* heart pop khi like */@keyframes monaPop{0%{transform:scale(1)}40%{transform:scale(1.35)}100%{transform:scale(1)}}.mona-clone-root.mona-jms .mona-eng-like.is-pop .icon img{animation:monaPop .35s ease}/* ---------- Rating 5 sao ---------- */.mona-clone-root.mona-jms .mona-rating{
  margin:26px 0 4px;padding:18px 20px;
  border:1px solid #ececf2;border-radius:14px;
  background:#fafafd;
  display:flex;flex-direction:column;gap:10px;
}.mona-clone-root.mona-jms .mona-rating-head{
  display:flex;align-items:baseline;justify-content:space-between;
  gap:12px;flex-wrap:wrap;
}.mona-clone-root.mona-jms .mona-rating-label{font-weight:700;font-size:16px;color:#1a1a1a}.mona-clone-root.mona-jms .mona-rating-score{font-size:14px;color:#6b6b76}.mona-clone-root.mona-jms .mona-rating-score strong{color:#1a1a1a;font-size:16px}.mona-clone-root.mona-jms .mona-rating-stars{display:inline-flex;gap:4px}.mona-clone-root.mona-jms .mona-star{
  border:0;background:none;padding:0;cursor:pointer;
  font-size:30px;line-height:1;color:#d6d6de;
  transition:color .12s ease,transform .12s ease;
  -webkit-tap-highlight-color:transparent;
}.mona-clone-root.mona-jms .mona-star:hover{transform:scale(1.12)}.mona-clone-root.mona-jms .mona-star.is-on{color:#ffb400}.mona-clone-root.mona-jms .mona-rating.is-rated .mona-star{cursor:default}.mona-clone-root.mona-jms .mona-rating.is-rated .mona-star:hover{transform:none}.mona-clone-root.mona-jms .mona-rating-thanks{font-size:14px;color:#1a9d4b;font-weight:600}/* thanh số cuối bài (view/like/share) */.mona-clone-root.mona-jms .mona-foot-bar{margin-top:18px}/* ---------- Box "Về tác giả" (E-E-A-T) ---------- */.mona-clone-root.mona-jms .mona-author-bio{
  display:flex;align-items:center;gap:26px;
  margin:30px 0 6px;padding:28px 30px;
  background:#f4f0fc;border:1px solid #e7defb;border-radius:18px;
}.mona-clone-root.mona-jms .mona-author-bio .mab-avatar{
  flex:0 0 auto;width:104px;height:104px;border-radius:50%;
  overflow:hidden;border:3px solid #7c4dff;display:block;
  box-shadow:0 4px 14px rgba(124,77,255,.18);
}.mona-clone-root.mona-jms .mona-author-bio .mab-avatar img{width:100%;height:100%;object-fit:cover;object-position:top center;display:block}/* Box author đầu bài dùng chung ảnh chân dung → cũng neo top cho khỏi cụt mặt */.mona-clone-root.mona-jms .mona-author .img-cir img{object-position:top center}.mona-clone-root.mona-jms .mona-author[data-author="minhnhut"] .img-cir img{width:100%;height:100%;object-fit:cover;object-position:top center}.mona-clone-root.mona-jms .mona-author-bio .mab-body{min-width:0}.mona-clone-root.mona-jms .mona-author-bio .mab-eyebrow{
  display:inline-block;font-size:11px;font-weight:700;letter-spacing:.12em;
  text-transform:uppercase;color:#9b7ddb;margin-bottom:6px;
}.mona-clone-root.mona-jms .mona-author-bio .mab-name{margin:0;font-size:20px;font-weight:700;line-height:1.25;color:#191726}.mona-clone-root.mona-jms .mona-author-bio .mab-name a{color:inherit;text-decoration:none}.mona-clone-root.mona-jms .mona-author-bio .mab-name a:hover{text-decoration:underline}.mona-clone-root.mona-jms .mona-author-bio .mab-role{margin:4px 0 10px;font-size:16px;font-weight:700;color:#7c3aed;line-height:1.35}.mona-clone-root.mona-jms .mona-author-bio .mab-desc{margin:0;font-size:16px;line-height:1.65;color:#2f2f3a}@media (max-width:575px){.mona-clone-root.mona-jms .mona-eng{gap:16px}.mona-clone-root.mona-jms .mona-eng .text{font-size:14px}.mona-clone-root.mona-jms .mona-star{font-size:27px}.mona-clone-root.mona-jms .mona-rating{padding:16px}.mona-clone-root.mona-jms .mona-author-bio{flex-direction:column;align-items:flex-start;gap:16px;padding:22px}.mona-clone-root.mona-jms .mona-author-bio .mab-avatar{width:84px;height:84px}.mona-clone-root.mona-jms .mona-author-bio .mab-name{font-size:18px}.mona-clone-root.mona-jms .mona-author-bio .mab-role, .mona-clone-root.mona-jms .mona-author-bio .mab-desc{font-size:15px}}
